pub const mirror = "varying vec2 v_texcoord;uniform sampler2D tex;void main () {  vec2 texturecoord = v_texcoord.xy;  float normcoord = texturecoord.x - 0.5;  normcoord *= sign (normcoord);  texturecoord.x = normcoord + 0.5;  gl_FragColor = texture2D (tex, texturecoord);}";
pub const squeeze = "varying vec2 v_texcoord;uniform sampler2D tex;void main () {  vec2 texturecoord = v_texcoord.xy;  vec2 normcoord = texturecoord - 0.5;  float r = length (normcoord)+0.01;  r = pow(r, 0.40)*1.3;  normcoord = normcoord / r;  texturecoord = (normcoord + 0.5);  gl_FragColor = texture2D (tex, texturecoord);}";
pub const stretch = "varying vec2 v_texcoord;uniform sampler2D tex;void main () {  vec2 texturecoord = v_texcoord.xy;  vec2 normcoord;  normcoord = texturecoord - 0.5;  float r = length (normcoord);  normcoord *= 2.0 - smoothstep(0.0, 0.35, r);  texturecoord = normcoord + 0.5;  gl_FragColor = texture2D (tex, texturecoord);}";
pub const tunnel = "varying vec2 v_texcoord;uniform sampler2D tex;void main () {  vec2 texturecoord = v_texcoord.xy;  vec2 normcoord;  normcoord = (texturecoord - 0.5);  float r = length(normcoord);  if (r > 0.0)    normcoord *= clamp (r, 0.0, 0.275) / r;  texturecoord = normcoord + 0.5;  gl_FragColor = texture2D (tex, texturecoord);}";
pub const fisheye = "varying vec2 v_texcoord;uniform sampler2D tex;void main () {  vec2 texturecoord = v_texcoord.xy;  vec2 normcoord;  normcoord = texturecoord - 0.5;  float r = length (normcoord);  normcoord *= r * 1.41421;  texturecoord = normcoord + 0.5;  gl_FragColor = texture2D (tex, texturecoord);}";
pub const twirl = "varying vec2 v_texcoord;uniform sampler2D tex;void main () {  vec2 texturecoord = v_texcoord.xy;  vec2 normcoord;  normcoord = texturecoord - 0.5;  float r = length (normcoord);  float phi = (1.0 - smoothstep (0.0, 0.3, r)) * 1.6;  float s = sin(phi);  float c = cos(phi);  normcoord *= mat2(c, s, -s, c);  texturecoord = normcoord + 0.5;  gl_FragColor = texture2D (tex, texturecoord);}";
pub const bulge = "varying vec2 v_texcoord;uniform sampler2D tex;void main () {  vec2 texturecoord = v_texcoord.xy;  vec2 normcoord;  normcoord = texturecoord - 0.5;  float r =  length (normcoord);  normcoord *= smoothstep (-0.05, 0.25, r);  texturecoord = normcoord + 0.5;  gl_FragColor = texture2D (tex, texturecoord);}";
pub const square = "varying vec2 v_texcoord;uniform sampler2D tex;void main () {  vec2 texturecoord = v_texcoord.xy;  vec2 normcoord;  normcoord = texturecoord - 0.5;  float r = length (normcoord);  normcoord *= 1.0 + smoothstep(0.125, 0.25, abs(normcoord));  normcoord /= 2.0; /* zoom amount */  texturecoord = normcoord + 0.5;  gl_FragColor = texture2D (tex, texturecoord);}";
pub const lumaThreshold = "varying vec2 v_texcoord;uniform sampler2D tex;void main () {  vec2 texturecoord = v_texcoord.xy;  vec4 color = texture2D(tex, texturecoord);  float luma = dot(color.rgb, vec3(0.2125, 0.7154, 0.0721));  gl_FragColor = vec4 (vec3 (smoothstep (0.30, 0.50, luma)), color.a);}";
pub const sepSobelLength = "varying vec2 v_texcoord;uniform sampler2D tex;uniform bool invert;void main () {  vec4 g = texture2D (tex, v_texcoord.xy);  g -= vec4(0.5, 0.5, 0.0, 0.0);  float len = length (g);  gl_FragColor = abs(vec4(vec3(float(invert) - len), 1.0));}";
pub const desaturate = "varying vec2 v_texcoord;uniform sampler2D tex;void main () {  vec4 color = texture2D (tex, v_texcoord.xy);  float luma = dot(color.rgb, vec3(0.2125, 0.7154, 0.0721));  gl_FragColor = vec4(vec3(luma), color.a);}";
pub const sepSobelHconv3 = "varying vec2 v_texcoord;uniform sampler2D tex;uniform float width;void main () {  float w = 1.0 / width;  vec2 texturecoord[3];  texturecoord[1] = v_texcoord.xy;  texturecoord[0] = texturecoord[1] - vec2(w, 0.0);  texturecoord[2] = texturecoord[1] + vec2(w, 0.0);  float grad_kern[3];  grad_kern[0] = 1.0;  grad_kern[1] = 0.0;  grad_kern[2] = -1.0;  float blur_kern[3];  blur_kern[0] = 0.25;  blur_kern[1] = 0.5;  blur_kern[2] = 0.25;  int i;  vec4 sum = vec4 (0.0);  for (i = 0; i < 3; i++) {     vec4 neighbor = texture2D(tex, texturecoord[i]);     sum.r = neighbor.r * blur_kern[i] + sum.r;    sum.g = neighbor.g * grad_kern[i] + sum.g;  }  gl_FragColor = sum + vec4(0.0, 0.5, 0.0, 0.0);}";
pub const sepSobelVconv3 = "varying vec2 v_texcoord;uniform sampler2D tex;uniform float height;void main () {  float h = 1.0 / height;  vec2 texturecoord[3];  texturecoord[1] = v_texcoord.xy;  texturecoord[0] = texturecoord[1] - vec2(0.0, h);  texturecoord[2] = texturecoord[1] + vec2(0.0, h);  float grad_kern[3];  grad_kern[0] = 1.0;  grad_kern[1] = 0.0;  grad_kern[2] = -1.0;  float blur_kern[3];  blur_kern[0] = 0.25;  blur_kern[1] = 0.5;  blur_kern[2] = 0.25;  int i;  vec4 sum = vec4 (0.0);  for (i = 0; i < 3; i++) {     vec4 neighbor = texture2D(tex, texturecoord[i]);     sum.r = neighbor.r * grad_kern[i] + sum.r;    sum.g = neighbor.g * blur_kern[i] + sum.g;  }  gl_FragColor = sum + vec4(0.5, 0.0, 0.0, 0.0);}";
pub const hconv7 = "varying vec2 v_texcoord;uniform sampler2D tex;uniform float kernel[7];uniform float gauss_width;void main () {  float w = 1.0 / gauss_width;  vec2 texturecoord[7];  texturecoord[3] = v_texcoord.xy;  texturecoord[2] = texturecoord[3] - vec2(w, 0.0);  texturecoord[1] = texturecoord[2] - vec2(w, 0.0);  texturecoord[0] = texturecoord[1] - vec2(w, 0.0);  texturecoord[4] = texturecoord[3] + vec2(w, 0.0);  texturecoord[5] = texturecoord[4] + vec2(w, 0.0);  texturecoord[6] = texturecoord[5] + vec2(w, 0.0);  int i;  vec4 sum = vec4 (0.0);  for (i = 0; i < 7; i++) {     vec4 neighbor = texture2D(tex, texturecoord[i]);     sum += neighbor * kernel[i];  }  gl_FragColor = sum;}";
pub const vconv7 = "varying vec2 v_texcoord;uniform sampler2D tex;uniform float kernel[7];uniform float gauss_height;void main () {  float h = 1.0 / gauss_height;  vec2 texturecoord[7];  texturecoord[3] = v_texcoord.xy;  texturecoord[2] = texturecoord[3] - vec2(0.0, h);  texturecoord[1] = texturecoord[2] - vec2(0.0, h);  texturecoord[0] = texturecoord[1] - vec2(0.0, h);  texturecoord[4] = texturecoord[3] + vec2(0.0, h);  texturecoord[5] = texturecoord[4] + vec2(0.0, h);  texturecoord[6] = texturecoord[5] + vec2(0.0, h);  int i;  vec4 sum = vec4 (0.0);  for (i = 0; i < 7; i++) {     vec4 neighbor = texture2D(tex, texturecoord[i]);    sum += neighbor * kernel[i];  }  gl_FragColor = sum;}";
pub const sum = "varying vec2 v_texcoord;uniform sampler2D base;uniform sampler2D blend;uniform float alpha;uniform float beta;void main () {  vec4 basecolor = texture2D (base, v_texcoord.xy);  vec4 blendcolor = texture2D (blend, v_texcoord.xy);  gl_FragColor = alpha * basecolor + beta * blendcolor;}";
pub const multiply = "varying vec2 v_texcoord;uniform sampler2D base;uniform sampler2D blend;uniform float alpha;void main () {  vec4 basecolor = texture2D (base, v_texcoord.xy);  vec4 blendcolor = texture2D (blend, v_texcoord.xy);  gl_FragColor = (1.0 - alpha) * basecolor + alpha * basecolor * blendcolor;}";
pub const lumaToCurve = "varying vec2 v_texcoord;uniform sampler2D tex;uniform sampler2D curve;void main () {  vec2 texturecoord = v_texcoord.xy;  vec4 color = texture2D (tex, texturecoord);  float luma = dot(color.rgb, vec3(0.2125, 0.7154, 0.0721));  color = texture2D (curve, vec2(luma, 0.0));  gl_FragColor = color;}";
pub const rgbToCurve = "varying vec2 v_texcoord;uniform sampler2D tex;uniform sampler2D curve;void main () {  vec4 color = texture2D (tex, v_texcoord.xy);  vec4 outcolor;  outcolor.r = texture2D (curve, vec2(color.r, 0.0)).r;  outcolor.g = texture2D (curve, vec2(color.g, 0.0)).g;  outcolor.b = texture2D (curve, vec2(color.b, 0.0)).b;  outcolor.a = color.a;  gl_FragColor = outcolor;}";
pub const sin = "varying vec2 v_texcoord;uniform sampler2D tex;void main () {  vec4 color = texture2D (tex, vec2(v_texcoord.xy));  float luma = dot(color.rgb, vec3(0.2125, 0.7154, 0.0721));  float cosh = color.r - 0.5*(color.g + color.b);  float sinh = 0.866*(color.g - color.b);  float sch = (1.0-sinh)*cosh;  float a = smoothstep (0.3, 1.0, sch);  float b = smoothstep (-0.4, -0.1, sinh);  float mix = a * b;  gl_FragColor = color * mix + luma * (1.0 - mix);}";
pub const interpolate = "varying vec2 v_texcoord;uniform sampler2D base;uniform sampler2D blend;void main () {vec4 basecolor = texture2D (base, v_texcoord);vec4 blendcolor = texture2D (blend, v_texcoord);vec4 white = vec4(1.0);gl_FragColor = blendcolor + (1.0 - blendcolor.a) * basecolor;}";
pub const textureInterp = "varying vec2 v_texcoord;uniform sampler2D base;uniform sampler2D blend;uniform sampler2D alpha;void main () {  vec4 basecolor = texture2D (base, v_texcoord);  vec4 blendcolor = texture2D (blend, v_texcoord);  vec4 alphacolor = texture2D (alpha, v_texcoord);  gl_FragColor = (alphacolor * blendcolor) + (1.0 - alphacolor) * basecolor;}";
pub const difference = "varying vec2 v_texcoord;uniform sampler2D saved;uniform sampler2D current;void main () {vec4 savedcolor = texture2D (saved, v_texcoord);vec4 currentcolor = texture2D (current, v_texcoord);gl_FragColor = vec4 (step (0.12, length (savedcolor - currentcolor)));}";
pub const conv9 = "varying vec2 v_texcoord;uniform sampler2D tex;uniform float kernel[9];uniform float width, height;uniform bool invert;void main () {  float w = 1.0 / width;  float h = 1.0 / height;  vec2 texturecoord[9];  texturecoord[4] = v_texcoord.xy;  texturecoord[5] = texturecoord[4] + vec2(w,   0.0);  texturecoord[2] = texturecoord[5] - vec2(0.0, h);  texturecoord[1] = texturecoord[2] - vec2(w,   0.0);  texturecoord[0] = texturecoord[1] - vec2(w,   0.0);  texturecoord[3] = texturecoord[0] + vec2(0.0, h);  texturecoord[6] = texturecoord[3] + vec2(0.0, h);  texturecoord[7] = texturecoord[6] + vec2(w,   0.0);  texturecoord[8] = texturecoord[7] + vec2(w,   0.0);  int i;  vec3 sum = vec3 (0.0);  for (i = 0; i < 9; i++) {     vec4 neighbor = texture2D (tex, texturecoord[i]);    sum += neighbor.xyz * kernel[i];  }  gl_FragColor = vec4 (abs(sum - vec3(float(invert))), 1.0);}";
